for i in [20,25]:
    if len(grid[i])==27: grid[i].append(5)
print([len(x) for x in grid])
filled=[]
for r,row in enumerate(grid):
    new=[]
    for c,v in enumerate(row):
        if v!=0: new.append(v)
        elif r==1: new.append(1)
        elif r==2: new.append(4)
        elif c==0 or c==1: new.append(1)
        elif c==2: new.append(4)
        else: new.append([1,3,5,7,9][(r+c)%5])
    filled.append(new)
print(sum(v==0 for row in filled for v in row))
print('\n'.join(' '.join(map(str,row)) for row in filled))
